nextflow.enable.types = true

/**
 * The pipeline's parameters. Add one here for each setting a user can change.
 */
params {
}

/**
 * The pipeline's entry workflow. Add processes and channels to the canvas to build it.
 */
workflow {
}

manifest {
    description = 'A blank Nextflow pipeline'
    nextflowVersion = '>=26.10.6'
}

nextflow.enable.types = true

include { SAY_HELLO } from './modules/local/say_hello/main.nf'

params {
    // The greeting to write to the output file.
    greeting: String = 'Hello, world!'
}

/**
 * Writes the greeting to a text file and publishes it.
 */
workflow {

    main:
    greetings = channel.of(params.greeting)
    greeting_file = SAY_HELLO(greetings)

    publish:
    greeting_file = greeting_file
}

output {
    greeting_file: Channel<Path> {
        path 'greetings'
    }
}

manifest {
    description = 'Writes a greeting to a text file'
    nextflowVersion = '>=26.10.6'
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Pipeline parameters",
  "description": "The parameters of the Hello world pipeline.",
  "type": "object",
  "$defs": {
    "greeting_options": {
      "title": "Greeting options",
      "type": "object",
      "description": "What the pipeline writes.",
      "properties": {
        "greeting": {
          "type": "string",
          "default": "Hello, world!",
          "description": "The greeting to write to the output file."
        }
      }
    }
  },
  "allOf": [{ "$ref": "#/$defs/greeting_options" }]
}

nextflow.enable.types = true

include { FASTQC } from './modules/local/fastqc/main.nf'
include { MULTIQC } from './modules/local/multiqc/main.nf'

/**
 * One row of the samplesheet.
 */
record Sample {
    id: String
    fastq_1: Path
    fastq_2: Path?
}

params {
    // The samplesheet: a CSV file with the columns id, fastq_1 and fastq_2 (fastq_2 may be empty).
    input: Channel<Sample>
}

/**
 * Checks the quality of each sample's reads with FastQC and summarises all samples in one MultiQC report.
 */
workflow {

    main:
    fastqc = FASTQC(params.input)
    reports = fastqc.flatMap { result -> result.reports }.collect()
    multiqc_report = MULTIQC(reports)
    versions = channel.topic('versions').unique()

    publish:
    fastqc = fastqc
    multiqc_report = multiqc_report
    versions = versions
}

output {
    fastqc {
        path 'fastqc'
    }
    multiqc_report {
        path 'multiqc'
    }
    versions {
        path 'pipeline_info'
    }
}

manifest {
    description = 'Quality control of sequencing reads with FastQC and MultiQC'
    nextflowVersion = '>=26.10.6'
}

profiles {
    test {
        params.input = "${projectDir}/assets/samplesheet.csv"
    }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Pipeline parameters",
  "description": "The parameters of the Samplesheet to MultiQC pipeline.",
  "type": "object",
  "$defs": {
    "input_output_options": {
      "title": "Input/output options",
      "type": "object",
      "description": "Where the pipeline finds its reads.",
      "required": ["input"],
      "properties": {
        "input": {
          "type": "string",
          "format": "file-path",
          "exists": true,
          "mimetype": "text/csv",
          "pattern": "^\\S+\\.csv$",
          "description": "The samplesheet: a CSV file with the columns id, fastq_1 and fastq_2. The fastq_2 cell may be empty for single-end reads."
        }
      }
    }
  },
  "allOf": [{ "$ref": "#/$defs/input_output_options" }]
}
